INSERT INTO tc_checkout_pilot_quote_ref (
    quote_ref, tenant_id, commerce_quote_id, owner_ref, scope_version, store_id, evidence_json, expires_at, created_at
) VALUES (
    #{quote.quoteRef}, #{tenant}, #{quote.commerceQuoteId}, #{quote.ownerRef}, #{quote.scopeVersion},
    #{quote.storeId}, #{quote.evidenceJson}, #{quote.expiresAt}, #{quote.createdAt}
)
ON DUPLICATE KEY UPDATE quote_ref = quote_ref

