UPDATE tc_checkout_pilot_quote_ref SET funding_application_id=#{funding.applicationId},
    funding_receipt_hash=#{funding.receiptHash}, funding_valid_until=#{funding.validUntil}
WHERE tenant_id=#{tenant} AND quote_ref=#{funding.reference} AND native_order_id=#{funding.orderId}
  AND funding_receipt_hash IS NULL AND #{funding.validUntil} > UTC_TIMESTAMP(3)
